
import ast
from pathlib import Path


# Local deterministic fixture for MOCK mode.
# This is NOT generated by a real AI model.
MOCK_CODE = '''
from collections import Counter


def analyze_text(text: str) -> dict:
    success = 0
    failures = Counter()
    events = Counter()
    invalid = 0

    for line in text.splitlines():
        if not line.strip():
            continue

        parts = line.split()

        if len(parts) != 5:
            invalid += 1
            continue

        date, time, level, event_id, action = parts

        if not event_id.startswith("event_"):
            invalid += 1
            continue

        if level == "INFO" and action == "upload_success":
            success += 1
        elif level == "ERROR":
            failures[action] += 1
        else:
            invalid += 1
            continue

        events[event_id] += 1

    failed = sum(failures.values())

    return {
        "total_records": success + failed,
        "success_count": success,
        "failure_count": failed,
        "invalid_count": invalid,
        "failure_types": dict(failures),
        "events": dict(events),
    }
'''


class DeveloperAgent:
    def __init__(self, model_client):
        self.model = model_client

    def run(
        self,
        requirement: str,
        plan: str,
        output_path: Path,
    ) -> Path:

        if self.model.mode == "mock":
            code = MOCK_CODE

        else:
            system_prompt = """
You are the Developer Agent in an AI development team.

Implement a Python log analyzer.

Requirements:
- Return ONLY valid Python source code.
- Do not use Markdown code fences.
- Use only the Python standard library.
- Implement analyze_text(text: str) -> dict.
- Support the exact five-field log format:
  YYYY-MM-DD HH:MM:SS LEVEL EVENT_ID ACTION
- Validate timestamps.
- Count successful uploads.
- Count failed uploads.
- Count malformed records.
- Count failures by error type.
- Count records by event ID.
- Empty lines should be ignored.
- Never crash on malformed log lines.

The result dictionary MUST contain:
total_records
success_count
failure_count
invalid_count
failure_types
events

Do not use network, subprocess, eval, exec,
external services, or production credentials.
Do not perform file operations at import time.

The module will be tested using pytest.
"""

            code = self.model.generate(
                system_prompt=system_prompt,
                user_prompt=(
                    "REQUIREMENTS:\n"
                    + requirement
                    + "\n\nDEVELOPMENT PLAN:\n"
                    + plan
                ),
            )

        code = code.strip()

        if code.startswith("```"):
            lines = code.splitlines()

            if lines[-1].strip() == "```":
                code = "\n".join(lines[1:-1])

        # Syntax validation only.
        # This does NOT establish that the code is safe.
        ast.parse(code, filename="analyzer.py")

        output_path.parent.mkdir(
            parents=True,
            exist_ok=True,
        )

        output_path.write_text(
            code + "\n",
            encoding="utf-8",
        )

        return output_path
